def priority(task, state, m=10.0, age=0.5):
    base = (m if task.tenant == 'premium' else 1.0) / max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    aging = 1.0 + age * wait / max(task.estimated_runtime, 1e-6)
    return base * aging  # tuned (m=26.8,age=0.722)

def priority(task, state, m=10.0, k=2.0, age_w=0.3, queue_thresh=0.5):
    import math
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    slack = max(0.0, task.due - est - state.now)
    atc = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    wait = state.now - task.release
    age = age_w * wait / est
    # when queue is long, emphasize urgency (ATC); when short, emphasize SPT/aging
    load = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    if load > queue_thresh:
        return atc * (1.0 + age)
    return tier / est * (1.0 + age)  # tuned (m=21.7,k=2.23,age_w=0.973,queue_thresh=1.97)

def priority(task, state, k=0.5, m=5.0, guard=3.0, spt_w=0.3):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    wait = state.now - task.release
    ratio = wait / est
    if ratio >= guard:
        return 1e6 * tier + atc
    return tier * (atc + spt_w / est)  # tuned (k=0.354,m=6.78,guard=2.79,spt_w=0.105)
